import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals["Statement"]
ws = wb["Statement"]

max_row = vws.max_row
target = "Invoice No."
found = None

for r in range(1, max_row + 1):
    v = vws.cell(row=r, column=1).value
    if v is not None and str(v).strip() == target:
        found = r
        break

if found is None:
    found = 1

def clean(val):
    if isinstance(val, str):
        val = val.strip()
        if val == "":
            return None
    return val

def set_value(sheet, row, col, val):
    try:
        sheet.cell(row=row, column=col).value = val
    except AttributeError:
        pass

# Place the located header in row 1, matching the intended macro result.
for c in range(1, 6):
    set_value(ws, 1, c, clean(vws.cell(row=found, column=c).value))

# Answer region: A2:E12.
# After deleting rows above `found`, final row r comes from original row r + found - 1.
for r in range(2, 13):
    src = r + found - 1
    for c in range(1, 6):
        if src <= max_row:
            val = vws.cell(row=src, column=c).value
        else:
            val = None
        set_value(ws, r, c, clean(val))

wb.save(OUT)

print("found_row:", found, "max_row:", max_row)
print("A1:", ws["A1"].value, "A2:", ws["A2"].value, "E12:", ws["E12"].value)
